using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace VNotch.Controls;

public enum TrayIconKind
{
    All, Pin, Links, Text, Code, Images, Colors, Files, Work, Ideas, Email,
    Shopping, Receipts, Personal, Important, Archive, Search, Lock, Unlock,
    Arrow, Keyboard, Pause, Resume, Info, Delete, Copy, More, Add, SelectAll
}

/// <summary>macOS-style vector symbols on a consistent 16-point coordinate grid.</summary>
public sealed class TrayIcon : Control
{
    public static readonly DependencyProperty KindProperty = DependencyProperty.Register(
        nameof(Kind), typeof(TrayIconKind), typeof(TrayIcon),
        new FrameworkPropertyMetadata(TrayIconKind.Text, FrameworkPropertyMetadataOptions.AffectsRender),
        value => value is TrayIconKind kind && Enum.IsDefined(kind));

    public TrayIconKind Kind { get => (TrayIconKind)GetValue(KindProperty); set => SetValue(KindProperty, value); }

    private static readonly IReadOnlyDictionary<TrayIconKind, Geometry> FilledSymbols = CreateFilledSymbols();
    private MatrixTransform? _viewport;

    static TrayIcon()
    {
        WidthProperty.OverrideMetadata(typeof(TrayIcon), new FrameworkPropertyMetadata(16d));
        HeightProperty.OverrideMetadata(typeof(TrayIcon), new FrameworkPropertyMetadata(16d));
        FocusableProperty.OverrideMetadata(typeof(TrayIcon), new FrameworkPropertyMetadata(false));
        IsHitTestVisibleProperty.OverrideMetadata(typeof(TrayIcon), new FrameworkPropertyMetadata(false));
        ForegroundProperty.OverrideMetadata(typeof(TrayIcon), new FrameworkPropertyMetadata(Brushes.White,
            FrameworkPropertyMetadataOptions.Inherits | FrameworkPropertyMetadataOptions.AffectsRender));
    }

    protected override void OnRenderSizeChanged(SizeChangedInfo sizeInfo)
    {
        base.OnRenderSizeChanged(sizeInfo);
        UpdateViewport();
    }

    private void UpdateViewport()
    {
        double scale = Math.Min(RenderSize.Width, RenderSize.Height) / 16;
        _viewport = new MatrixTransform(scale, 0, 0, scale,
            (RenderSize.Width - 16 * scale) / 2, (RenderSize.Height - 16 * scale) / 2);
        _viewport.Freeze();
    }

    protected override void OnRender(DrawingContext drawingContext)
    {
        base.OnRender(drawingContext);
        if (RenderSize.Width <= 0 || RenderSize.Height <= 0) return;
        // WPF can render before delivering the deferred SizeChanged notification.
        double scale = Math.Min(RenderSize.Width, RenderSize.Height) / 16;
        if (_viewport == null || Math.Abs(_viewport.Matrix.M11 - scale) > 1e-6 ||
            Math.Abs(_viewport.Matrix.OffsetX - (RenderSize.Width - 16 * scale) / 2) > 1e-6 ||
            Math.Abs(_viewport.Matrix.OffsetY - (RenderSize.Height - 16 * scale) / 2) > 1e-6)
            UpdateViewport();
        drawingContext.PushTransform(_viewport);
        if (FilledSymbols.TryGetValue(Kind, out var filled))
            drawingContext.DrawGeometry(Foreground, null, filled);
        drawingContext.Pop();
    }

